91: static int openattr(pid_t pid, const char *attr, int flags)
92: {
93: 	int fd, rc;
94: 	char path[44]; /* must hold "/proc/self/task/%d/attr/sockcreate" */
95: 	pid_t tid;
96: 
97: 	static_assert(sizeof(pid_t) <= sizeof(uint32_t),
98: 		      "content written to path might get truncated");
99: 
100: 	if (pid > 0) {
101: 		rc = snprintf(path, sizeof(path), "/proc/%d/attr/%s", pid,
102: 			      attr);
103: 	} else if (pid == 0) {
104: 		rc = snprintf(path, sizeof(path), "/proc/thread-self/attr/%s",
105: 			      attr);
106: 		if (rc < 0 || (size_t)rc >= sizeof(path)) {
107: 			errno = EOVERFLOW;
108: 			return -1;
109: 		}
110: 		fd = open(path, flags | O_CLOEXEC);
111: 		if (fd >= 0 || errno != ENOENT)
112: 			return fd;
113: 		tid = selinux_gettid();
114: 		rc = snprintf(path, sizeof(path), "/proc/self/task/%d/attr/%s",
115: 			      tid, attr);
116: 	} else {
117: 		errno = EINVAL;
118: 		return -1;
119: 	}
120: 	if (rc < 0 || (size_t)rc >= sizeof(path)) {
121: 		errno = EOVERFLOW;
122: 		return -1;
123: 	}
124: 
125: 	return open(path, flags | O_CLOEXEC);
126: }
