128: static int getprocattrcon_raw(char **context, pid_t pid, const char *attr,
129: 			      const char *prev_context)
130: {
131: 	char *buf;
132: 	size_t size;
133: 	int fd;
134: 	ssize_t ret;
135: 	int errno_hold;
136: 
137: 	__selinux_once(once, init_procattr);
138: 	init_thread_destructor();
139: 
140: 	if (prev_context && prev_context != UNSET) {
141: 		*context = strdup(prev_context);
142: 		if (!(*context)) {
143: 			return -1;
144: 		}
145: 		return 0;

146: 	}
147: 
148: 	fd = openattr(pid, attr, O_RDONLY | O_CLOEXEC);
149: 	if (fd < 0)
150: 		return -1;
151: 
152: 	size = selinux_page_size;
153: 	buf = calloc(1, size);
154: 	if (!buf) {
155: 		ret = -1;
156: 		goto out;
157: 	}
158: 
159: 	do {
160: 		ret = read(fd, buf, size - 1);
161: 	} while (ret < 0 && errno == EINTR);
162: 	if (ret < 0)
163: 		goto out;
164: 
165: 	if (ret == 0) {
166: 		*context = NULL;
167: 		goto out;
168: 	}
169: 
170: 	*context = strdup(buf);
171: 	if (!(*context)) {
172: 		ret = -1;
173: 		goto out;
174: 	}
175: 	ret = 0;
176: out:
177: 	free(buf);
178: 	errno_hold = errno;
179: 	close(fd);
180: 	errno = errno_hold;
181: 	return ret;
182: }
